export default async function plan({ body, statusCode, chatId }, context) {
  if (!Number.isInteger(statusCode) || statusCode < 200 || statusCode >= 300)
    throw Error("YouTube search failed");
  if (!body || typeof body !== "object" || Array.isArray(body) || body.error)
    throw Error("Invalid YouTube response");
  const items = body.items ?? [];
  if (!Array.isArray(items) || items.length > 4) throw Error("Invalid YouTube result list");
  if (!items.length) return { rows: [], chatId };
  if (typeof chatId !== "string" || !chatId.trim() || chatId === "YOUR_TELEGRAM_CHAT_ID")
    throw Error("Set a Telegram chat ID");
  const rows = items.map((x) => {
    const id = x?.id?.videoId,
      title = x?.snippet?.title;
    if (typeof id !== "string" || !/^[A-Za-z0-9_-]{1,128}$/.test(id) || typeof title !== "string")
      throw Error("Invalid video");
    const escaped = title.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    const text = `New video on YouTube!\n<b>${escaped}</b>\n\nhttps://youtu.be/${id}`;
    if (text.length > 4096) throw Error("Telegram message exceeds limit");
    return { id, text };
  });
  const old = await context.state.get("youtube-video-ids");
  if (old !== null && (!Array.isArray(old) || old.some((x) => typeof x !== "string")))
    throw Error("Invalid saved IDs");
  const previous = old ?? [],
    selected = [];
  for (const row of rows) {
    if (previous.includes(row.id)) break;
    selected.push(row);
  }
  await context.state.set(
    "youtube-video-ids",
    rows.map((x) => x.id),
  );
  return { rows: selected, chatId };
}

