export default function next({ rows, previousState }) {
  if (!Array.isArray(rows) || rows.length > 4) throw Error("Invalid notices");
  const index = previousState === null ? 0 : previousState.index + 1;
  if (!Number.isInteger(index) || index < 0 || index > rows.length) throw Error("Invalid progress");
  return {
    state: { index },
    more: index < rows.length,
    text: rows[index]?.text ?? "-",
    count: rows.length,
  };
}
